from engine import span
def build(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(role='purpose', text='Don Quijote de la Mancha, de Miguel de Cervantes, es la obra más destacada de la literatura española y una de las primeras novelas modernas. Este capítulo explica cómo se publicó, cómo se estructuran sus dos partes, qué técnicas narrativas la hacen innovadora y por qué ha influido tanto en la narrativa posterior.',
        quotes=[Q('es_quijote','es considerada la obra más destacada de la literatura española y una de las más importantes de la literatura universal'), Q('en_quijote','It is considered a founding work of Western literature and the first modern novel.')]))
    P.append(dict(text='La primera parte, El ingenioso hidalgo don Quijote de la Mancha, lleva fecha de 1605, aunque se imprimió en diciembre de 1604. Cervantes redactó el prólogo en agosto de 1604, el privilegio real se firmó el 26 de septiembre y el editor fue Francisco de Robles, que encargó la impresión a la casa de Juan de la Cuesta. La edición tuvo una calidad mediocre y muchas erratas, y se reimprimió en el mismo año, de modo que existen dos ediciones autorizadas de 1605, además de dos piratas publicadas en Lisboa. Según una fuente en inglés, el libro salió a la venta el 16 de enero de 1605.',
        quotes=[Q('es_quijote','publicada con fecha de 1605, aunque impresa en diciembre de 1604'), Q('es_quijote','Robles encargó la impresión de esta primera parte a la casa de Juan de la Cuesta'), Q('es_quijote','hay en realidad dos ediciones autorizadas de 1605'), Q('en_quijote','the book came out on 16 January 1605')]))
    P.append(dict(text='Cervantes no ganó mucho dinero con el éxito: había vendido todos los derechos de la obra a su editor. La primera parte triunfó como obra cómica, no como obra seria. Esto, unido al ataque a Lope de Vega del prólogo, provocó que en 1614 apareciese una segunda parte apócrifa firmada por Alonso Fernández de Avellaneda, con pie de imprenta falso, cuyo prólogo insultaba a Cervantes. Nadie sabe con certeza quién fue Avellaneda, y las propuestas son numerosas, entre ellas la de Jerónimo de Pasamonte, defendida por Martín de Riquer.',
        quotes=[Q('es_quijote','No supuso un gran beneficio económico para el autor, quien había vendido todo el derecho de la obra a su editor Francisco de Robles.'), Q('es_quijote','saliera una segunda parte apócrifa de la obra bajo el nombre autoral'), Q('en_quijote','there is no consensus as to who he was')]))
    P.append(dict(text='La verdadera segunda parte se publicó en 1615 con el título de Segunda parte del ingenioso caballero don Quijote de la Mancha. En ella los protagonistas saben que su historia ya es un libro: otros personajes han leído la primera parte y los reconocen, y Cervantes responde con ironía a Avellaneda, hasta el punto de que don Quijote y Sancho se topan con Álvaro Tarfe, un personaje de la continuación apócrifa, y le hacen jurar que el otro don Quijote es un impostor.',
        quotes=[Q('es_quijote','En 1615 se publicó la continuación auténtica de la historia de don Quijote'), Q('es_quijote','algunos de los personajes que aparecerán en lo sucesivo han leído el libro y los reconocen'), Q('en_quijote','make him swear that the "other" Quixote and Sancho are impostors')]))
    P.append(dict(text='La estructura de la primera parte imita la del Amadís de Gaula: la obra consta de cincuenta y dos capítulos separados en cuatro partes de 8, 6, 14 y 24 capítulos. La segunda parte tiene setenta y cuatro capítulos. Para sus primeros lectores, sin embargo, era un libro de un solo volumen, dividido internamente en cuatro partes, no la primera mitad de una obra en dos. En ambas se intercalan historias de varios géneros, como la de Grisóstomo y Marcela o la novela de El curioso impertinente, y la primera parte se narra en tres salidas: dos en la primera, con la segunda ya acompañado de Sancho, y la tercera en la segunda parte.',
        quotes=[Q('es_quijote','consta de 52 capítulos, separados a su vez en cuatro partes de 8, 6, 14 y 24 capítulos, respectivamente'), Q('es_quijote','consta de 74 capítulos'), Q('en_quijote','a one-volume book published in 1605, divided internally into four parts'), Q('es_quijote','Grisóstomo y la pastora Marcela, la novela de El curioso impertinente')]))
    P.append(dict(text='El argumento arranca con un hidalgo pobre de La Mancha, Alonso Quijano, de casi cincuenta años según una fuente, que enloquece leyendo libros de caballerías y se cree caballero andante. Se pone por nombre don Quijote de la Mancha, bautiza a su caballo Rocinante, elige como dama a una labradora, Aldonza Lorenzo, a la que llama Dulcinea del Toboso, y es armado caballero en una venta que confunde con un castillo. En su segunda salida lo acompaña como escudero el labrador Sancho Panza, al que promete el gobierno de una ínsula, y juntos viven aventuras como la de los molinos de viento, que don Quijote toma por gigantes.',
        quotes=[Q('es_quijote','La novela comienza describiendo a un hidalgo pobre','se cree un caballero andante medieval.'), Q('es_quijote','bautiza a su caballo como Rocinante'), Q('en_quijote','Alonso Quixano is an hidalgo nearing 50 years of age'), Q('es_quijote','Don Quijote lucha contra unos gigantes, que no son otra cosa que molinos de viento')]))
    P.append(dict(text='La técnica más característica es el contraste entre lo idealizado y lo real, que se da en todos los niveles: en el estilo, que unas veces usa toda la retórica y otras imita el lenguaje popular, y en los personajes, que Cervantes coloca en parejas para que se construyan mediante el diálogo. Con el avance de la obra, don Quijote se sanchifica y Sancho se quijotiza. A esta mezcla de puntos de vista se le llama perspectivismo.',
        quotes=[Q('es_quijote','El contraste entre lo idealizado y lo real, que se da a todos los niveles'), Q('es_quijote','don Quijote se sanchifica y Sancho se quijotiza'), Q('es_quijote','Esta mezcla y superposición de perspectivas se denomina perspectivismo.'), Q('en_quijote','The contrasts between the tall, thin, fancy-struck and idealistic Quixote and the fat diddy, world-weary Panza is a motif echoed ever since')]))
    P.append(dict(text='Cervantes juega además con la metaficción. En el capítulo 9 explica que no tenía el resto del manuscrito, que atribuye a un historiador árabe, Cide Hamete Benengeli, y que lo encontró paseando por Toledo. Estos intermediarios narrativos difuminan al autor y hacen la obra menos literaria y más realista. En palabras de la crítica, la primera parte es una ficción de segundo grado, en la que el personaje influye en los hechos, y la segunda, una de tercer grado, en la que el personaje transforma los hechos y es transformado por ellos.',
        quotes=[Q('es_quijote','que no tenía los manuscritos de la continuación','Cide Hamete Benengeli'), Q('es_quijote','Utiliza juegos metaficcionales a fin de difuminar y hacer desaparecer la figura del autor del texto'), Q('en_quijote','the rest were translated from an Arabic text by the Moorish historian Cide Hamete Benengeli'), Q('es_quijote','Por primera vez en una novela europea, el personaje transforma los hechos y al mismo tiempo es transformado por ellos.')]))
    P.append(dict(text='El lenguaje también es un recurso. Los nombres juegan con la contradicción y la ironía: Rocinante es una inversión y Dulcinea alude a la ilusión. Según una de las fuentes, don Quijote habla un castellano antiguo, imitación del de los libros de caballerías, que provoca risa porque muchas veces nadie lo entiende, mientras el resto de los personajes habla el español de finales del siglo XVI. Otra fuente añade que la oralidad del lenguaje cervantino acerca al lector a los personajes y favorece su identificación con ellos.',
        quotes=[Q('en_quijote','such as the names Rocinante (a reversal) and Dulcinea (an allusion to illusion)'), Q('en_quijote','Old Castilian is spoken only by Don Quixote, while the rest of the roles speak a contemporary (late 16th century) version of Spanish.'), Q('es_quijote','La oralidad del lenguaje cervantino','facilitando su identificación y complicidad con ellos')]))
    P.append(dict(text='La obra influyó de modo enorme en la narrativa posterior: se ha llegado a decir que toda novela posterior reescribe el Quijote o lo contiene implícitamente. Sin embargo, en España Cervantes casi no tuvo seguidores hasta el realismo del siglo XIX, con Benito Pérez Galdós. Fuera de España, el Quijote dio la palabra quixotic al inglés y la expresión tilting at windmills, que significa atacar enemigos imaginarios. En 2002, en una votación entre cien escritores de 54 nacionalidades, ocupó el primer puesto entre las mejores obras literarias de la historia.',
        quotes=[Q('es_quijote','toda novela posterior reescribe el Quijote o lo contiene implícitamente'), Q('es_quijote','Solamente renacerá Cervantes como modelo novelístico en España con la llegada del realismo.'), Q('en_quijote','Tilting at windmills is an English language idiom that means "attacking imaginary enemies".')]))
    P.append(dict(role='definition', text='Perspectivismo: procedimiento narrativo por el que cada hecho es descrito por cada personaje desde una cosmovisión distinta, de modo que la realidad se vuelve compleja y rica en matices. En el Quijote nace del diálogo entre don Quijote y Sancho; un ejemplo es la oposición entre quijotización y sanchificación que señaló Salvador de Madariaga.',
        quotes=[Q('es_quijote','El perspectivismo hace que cada hecho sea descrito por cada personaje en función de una cosmovisión distinta'), Q('es_quijote','Esta mezcla y superposición de perspectivas se denomina perspectivismo.'), Q('en_quijote','opposing Quixotization with Sanchification')]))
    P.append(dict(role='consejo', text='Al leer el Quijote, distinga siempre quién cuenta cada episodio y con qué grado de fiabilidad: el narrador, el supuesto historiador árabe, don Quijote o Sancho. Anotar quién interpreta cada escena le ayudará a ver cómo el mismo hecho, como los molinos, cambia de sentido según la voz.',
        quotes=[Q('es_quijote','Utiliza juegos metaficcionales a fin de difuminar y hacer desaparecer la figura del autor del texto'), Q('en_quijote','Even faithful and simple Sancho is forced to deceive him at certain points.')]))
    P.append(dict(role='self_check', text='¿Por qué se publicó una segunda parte apócrifa en 1614 y cómo responde Cervantes a ella dentro de la novela? ¿Qué diferencias hay entre la ficción de segundo grado y la de tercer grado? ¿Qué significa que don Quijote se sanchifica y Sancho se quijotiza?',
        quotes=[Q('es_quijote','Eso motivó que, en 1614, saliera una segunda parte apócrifa'), Q('es_quijote','Constituye una ficción de segundo grado, es decir, el personaje influye en los hechos.'), Q('en_quijote','a spurious Part Two, entitled Second Volume of the Ingenious Gentleman Don Quixote of La Mancha')]))
    return P

def _legacy_numeric_problems(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    return [dict(role='worked', problem_type='NUMERICAL',
        prompt='La primera parte del Quijote se publicó en 1605 y la segunda, la auténtica, en 1615. En 1614 apareció la continuación apócrifa de Avellaneda. Calcule cuántos años separan las dos partes de Cervantes y qué porcentaje de ese intervalo había transcurrido cuando salió la obra apócrifa.',
        expected='90', quotes=[Q('es_quijote','En 1615 apareció su continuación con el título de Segunda parte del ingenioso caballero don Quijote de la Mancha'), Q('en_quijote','In 1614 a fake second part was published by a mysterious author under the pen name Avellaneda')],
        method='Diferencia de años y proporción porcentual',
        solution=dict(given=[dict(symbol='a_1',value=1605,unit='dimensionless',meaning='año de la primera parte'),dict(symbol='a_2',value=1615,unit='dimensionless',meaning='año de la segunda parte auténtica'),dict(symbol='a_A',value=1614,unit='dimensionless',meaning='año de la continuación apócrifa')],
          unknown='Los años entre las dos partes y el porcentaje transcurrido cuando salió la apócrifa.',
          model=[dict(name='Intervalo entre las partes',latex='\\Delta = a_2 - a_1',symbolic='a_2-a_1'),dict(name='Porcentaje transcurrido',latex='p = 100\\,\\frac{a_A - a_1}{\\Delta}',symbolic='100*(a_A-a_1)/(a_2-a_1)')],
          assumptions=['Solo se cuentan años de calendario, sin distinguir el mes de publicación.'],
          development=['La obra apócrifa se sitúa dentro del intervalo entre las dos partes de Cervantes, así que el porcentaje debe estar entre 0 y 100.'],
          steps=[dict(text='Años entre las dos partes',equation='\\Delta = 1615 - 1605',expression='1615-1605',expected=10,unit='dimensionless'),
                 dict(text='Porcentaje transcurrido',equation='p = 100 \\cdot (1614 - 1605)/10',expression='100*(1614-1605)/(1615-1605)',expected=90,unit='dimensionless')],
          result='Entre las dos partes pasaron 10 años, y la obra apócrifa apareció cuando ya había transcurrido el 90 % de ese intervalo.',
          interpretation='Avellaneda se adelantó a Cervantes un año antes de su continuación, lo que ayuda a explicar que la segunda parte auténtica responda a su rival dentro de la propia novela.',
          limitations=['Las fechas de portada no siempre coinciden con las de impresión: la primera parte se imprimió en diciembre de 1604 aunque lleva fecha de 1605.'],
          mistakes=['Dividir por 1614 - 1605 en lugar de por el intervalo total entre las dos partes auténticas.']))]


